import itertools, re, random
from accountability.authorization import intersection_pattern, pattern_matches

# brute-force oracle: try strings over alphabet {a,b,c,x,y} up to length 5
ALPHABET = "abcxy"
STRINGS = [""]
for n in range(1,6):
    STRINGS += ["".join(t) for t in itertools.product(ALPHABET, repeat=n)]

def matches(pattern, s):
    regex = ".*".join(re.escape(p) for p in pattern.split("*"))
    return re.fullmatch(regex, s, re.DOTALL) is not None

def oracle_intersection(p, q):
    common = [s for s in STRINGS if matches(p,s) and matches(q,s)]
    if not common:
        return None
    return common

patterns = set()
# generate globs from alphabet with 1-3 stars and short literals
lits = ["", "a", "b", "ab", "a", "x", "y", "aa", "b"]
random.seed(1)
for _ in range(2000):
    nstar = random.choice([0,1,1,2,2,3])
    parts = [random.choice(lits) for _ in range(nstar+1)]
    patterns.add("*".join(parts))
# add targeted patterns
for p in ["*a*b*","*b*a*","a*b","*a*a*","*a**","a*","*a","**","a**b",
          "*aa*","*ab*","*ba*","a*b*a","*a*b*a*","*x*y*","*a*b*b*","*a*a*b*"]:
    patterns.add(p)

def check_intersection_glob(g, p, q):
    # every match of g must match both p and q (exactness), over bounded strings
    for s in STRINGS:
        if matches(g, s) and not (matches(p,s) and matches(q,s)):
            return ("too-broad", s)
    # g must match at least all common strings... can't verify fully with bounded set,
    # but check every found common string is matched by g
    for s in STRINGS:
        if matches(p,s) and matches(q,s) and not matches(g,s):
            return ("too-narrow", s)
    return None

bugs = []
plist = sorted(patterns)
for i, p in enumerate(plist):
    for q in plist[i:]:
        common = oracle_intersection(p, q)
        g = intersection_pattern(p, q)
        g_rev = intersection_pattern(q, p)
        if (common is None) != (g is None):
            bugs.append(("exist-mismatch", p, q, common is not None, g))
            continue
        if g is not None:
            bad = check_intersection_glob(g, p, q)
            if bad:
                bugs.append(("glob-"+bad[0], p, q, g, bad[1]))
            if g != g_rev:
                bugs.append(("asymmetry", p, q, g, g_rev))

for b in bugs[:40]:
    print(b)
print("total bugs:", len(bugs), "out of", len(plist)*(len(plist)+1)//2, "pairs")
EOF

