import itertools, random
from accountability.authorization import (
    intersection_pattern, _merge_middle_runs, _middle_runs_compatible,
    _common_supersequence_lengths,
)

# Independent oracle over token sequences (fragments are atomic tokens):
#  - compatible iff a monotone alignment of equal tokens exists, i.e. the
#    shortest common supersequence needs exactly sum(max counts) tokens.
#  - canonical intersection = lexicographically smallest SCS.
ALPHA = ["a", "b", "x"]

def scs_length(A, B):
    n, m = len(A), len(B)
    L = [[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1): L[i][m] = n-i
    for j in range(m+1): L[n][j] = m-j
    for i in range(n-1,-1,-1):
        for j in range(m-1,-1,-1):
            if A[i]==B[j]:
                L[i][j] = 1+L[i+1][j+1]
            else:
                L[i][j] = 1+min(L[i+1][j], L[i][j+1])
    return L[0][0]

def compatible_oracle(A, B):
    cnt = {}
    for t in A: cnt[t] = cnt.get(t,0)+1
    cb = {}
    for t in B: cb[t] = cb.get(t,0)+1
    shared = sum(max(cnt.get(t,0), cb.get(t,0)) for t in set(cnt)|set(cb))
    return scs_length(A,B) == shared

def scs_all(A, B):
    # brute force: enumerate all supersequence strings of tokens up to target len
    target = scs_length(A, B)
    results = set()
    def is_super(S, X):
        it = iter(S)
        return all(tok in it for tok in X)
    for cand in itertools.product(sorted(set(A)|set(B)), repeat=target):
        if is_super(cand, A) and is_super(cand, B):
            results.add(cand)
    return results

seqs = []
for n in range(0,5):
    seqs += [list(s) for s in itertools.product(ALPHA, repeat=n)]
random.seed(0); random.shuffle(seqs); seqs = seqs[:180]

bugs = 0
for A in seqs:
    for B in seqs:
        A, B = tuple(A), tuple(B)
        comp = _middle_runs_compatible(A, B)
        ora = compatible_oracle(A, B)
        if comp != ora:
            print("COMPAT MISMATCH", A, B, comp, ora); bugs += 1; continue
        if comp:
            merged = _merge_middle_runs(A, B)
            merged_rev = _merge_middle_runs(B, A)
            allscs = scs_all(A, B)
            if merged not in allscs:
                print("MERGE NOT AN SCS", A, B, merged); bugs += 1
            elif merged != min(allscs):
                print("MERGE NOT LEX MIN", A, B, merged, min(allscs)); bugs += 1
            if merged != merged_rev:
                print("MERGE ASYMMETRY", A, B, merged, merged_rev); bugs += 1
print("token-model bugs:", bugs)
