import itertools
from accountability.authorization import intersection_pattern, pattern_matches

# Blocks cannot occur accidentally across boundaries (boundary text is ")("
# and a block like "(a)" cannot span it); filler chars 0/1 never complete a
# block, so char-level glob matching coincides with the token-sequence model.
BLOCK = {"a": "(a)", "b": "(b)", "x": "(x)"}
FILLERS = ["", "0"]

def seq_to_lit(seq):
    return "".join(BLOCK[t] for t in seq)

# patterns: prefix 0-1 blocks, middles 0-3 blocks, suffix 0-1 blocks
def all_patterns():
    pats = set()
    toks = ["a","b","x"]
    pre_opts = [()] + [(t,) for t in toks]
    suf_opts = pre_opts
    mid_seqs = [()]
    for n in range(1,4):
        mid_seqs += list(itertools.product(toks, repeat=n))
    for pre in pre_opts:
        for suf in suf_opts:
            for mid in mid_seqs:
                lit = seq_to_lit(pre)
                s = seq_to_lit(suf)
                mids = seq_to_lit(mid)
                pats.add("*".join([lit, *([mids] if mid else []), s]) if False else
                         lit + ("*" + "*".join(seq_to_lit((t,)) for t in mid) if mid else "*") + s)
    # simpler explicit construction
    pats = set()
    for pre in pre_opts:
        for suf in suf_opts:
            for mid in mid_seqs:
                parts = [seq_to_lit(pre)] + [BLOCK[t] for t in mid] + [seq_to_lit(suf)]
                pats.add("*".join(parts))
    return sorted(pats)

PATS = all_patterns()
print("num patterns:", len(PATS))

# enumerated universe of strings: filler?, blocks(0..5) joined with filler?, filler?
STRINGS = set()
for n in range(0,6):
    for seq in itertools(["a","b","x"], repeat=n) if False else itertools.product("abx", repeat=n):
        core = "".join(BLOCK[t] for t in seq)
        for f1 in FILLERS:
            for f2 in FILLERS:
                STRINGS.add(f1 + core + f2)
                # also filler between blocks
                STRINGS.add(f1 + "0".join(BLOCK[t] for t in seq) + f2)
STRINGS = sorted(STRINGS)
print("num strings:", len(STRINGS))

bugs = 0
checked = 0
for i, p in enumerate(PATS):
    pm = {s: pattern_matches(p, s) for s in STRINGS}
    for q in PATS[i:]:
        g = intersection_pattern(p, q)
        gr = intersection_pattern(q, p)
        if g != gr:
            print("ASYMMETRY", p, q, g, gr); bugs += 1
        for s in STRINGS:
            both = pm[s] and pattern_matches(q, s)
            gm = g is not None and pattern_matches(g, s)
            if gm and not both:
                print("TOO BROAD", repr(p), repr(q), repr(g), "string", repr(s)); bugs += 1
                break
            if both and not gm:
                print("TOO NARROW / EXISTENCE", repr(p), repr(q), g, "string", repr(s)); bugs += 1
                break
        checked += 1
        if bugs > 15: break
    if bugs > 15: break
print("pairs checked:", checked, "bugs:", bugs)
