def build(pre, mids, suf):
    return "*".join([BLOCK[pre] if pre else ""] +
                    [BLOCK[t] for t in mids] +
                    [BLOCK[suf] if suf else ""])

# all (pre in {None,a,b,x}) x mids(0..3) x suf ; construct patterns
PATS = set()
