        reported = g is not None
        if actually and not reported:
            existence_wrong.append(("missed-candidate",p,q,common[:3]))
        elif reported and not actually:
            existence_wrong.append(("false-candidate",p,q))
        elif reported:
            for s in common:
                if not pattern_matches(g,s):
                    narrow.append((p,q,g,s)); break
            for k,s in enumerate(STRINGS):
                if pattern_matches(g,s) and not (pm[k] and pattern_matches(q,s)):
                    broad.append((p,q,g,s)); break
print("EXISTENCE ERRORS:", len(existence_wrong))
